#!/usr/bin/env node
/**
 * speech-engine/index.js — executable entry point for the LyricDisplay
 * speech engine (Phase 2 scaffold).
 *
 * Usage:
 *   node index.js [--engine=fake|whisper] [--host=127.0.0.1] [--port=4731]
 *                 [--bin-dir=DIR] [--models-dir=DIR] [--model=ID]
 *
 * Environment (set by LyricDisplay's supervisor when it forks us):
 *   LD_SPEECH_TOKEN   per-launch secret required on every request (REQUIRED
 *                     — generated by the supervisor; never printed here)
 *   LD_SPEECH_HOST    bind host, loopback only (default 127.0.0.1)
 *   LD_SPEECH_PORT    bind port, 0 = ephemeral (default 4731)
 *   LD_SPEECH_ENGINE  engine kind (default fake)
 *
 * Modes:
 *   fake     (default) canned engine from fakeEngine.js — no model, no
 *            binary, no download. This is what makes Phase 2 verifiable, and
 *            it stays reachable ONLY when explicitly asked for.
 *   whisper  the real thing (Phase 5). A checksum-verified whisper.cpp CLI is
 *            spawned as a child process and fed WAV over stdin; see
 *            drivers/whispercpp.js for why a subprocess and not a native addon.
 *            If the binary or the weights are absent the process exits 2 with
 *            an actionable message — it never silently falls back to the canned
 *            engine, because a green "listening" badge over canned text on a
 *            sanctuary screen is the worst failure this program has.
 *
 * Security invariants enforced here and in server.js:
 *   - binds loopback ONLY (assertLoopbackBindHost throws otherwise)
 *   - token required on every request
 *   - the token is NEVER logged or printed, not even on startup
 *
 * Process protocol (fork IPC, mirrored from main/backend.js):
 *   parent <- { status: 'ready', host, port, apiVersion, wsPath }
 *   parent <- { status: 'error', error: 'EADDRINUSE', port }
 *   parent <- { t, ... }  message-bus mirror (see bus.js)
 *
 * Transports on ONE port (plan section 3):
 *   REST   /v1/...      main -> engine (health, session, transcribe)
 *   WS     /v1/stream   renderer -> engine: raw PCM frames, back to back;
 *                       engine -> renderer: the same JSON messages the
 *                       parent-process mirror forwards. Both share the
 *                       loopback bind, the launch token (header on REST,
 *                       `?token=` on the upgrade), and the bus.
 */
import { generateEngineToken, SPEECH_PROTOCOL_VERSION } from '../shared/speech/protocol.js';
import { createSpeechEngineServer, DEFAULT_BIND_HOST } from './server.js';
import { attachWebSocketTransport, WS_PATH } from './wsTransport.js';
import { createFakeEngine } from './fakeEngine.js';
import { createWhisperEngine, binaryName } from './drivers/whispercpp.js';
import { createMessageBus } from './bus.js';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

function parseArgs(argv) {
  const out = {};
  for (const arg of argv) {
    const match = /^--([a-zA-Z-]+)(?:=(.*))?$/.exec(arg);
    if (match) out[match[1]] = match[2] === undefined ? true : match[2];
  }
  return out;
}

const args = parseArgs(process.argv.slice(2));
const env = process.env;

const engineKind = String(args.engine ?? env.LD_SPEECH_ENGINE ?? 'fake');

const host = String(args.host ?? env.LD_SPEECH_HOST ?? DEFAULT_BIND_HOST);
const port = Number(args.port ?? env.LD_SPEECH_PORT ?? 4731);
const token = typeof args.token === 'string' && args.token.length >= 16
  ? args.token
  : (typeof env.LD_SPEECH_TOKEN === 'string' && env.LD_SPEECH_TOKEN.length >= 16
      ? env.LD_SPEECH_TOKEN
      : generateEngineToken());

const bus = createMessageBus();

/**
 * Where the engine's binary and weights live.
 *
 * Resolved from the supervisor's environment, with the documented drop-in
 * directory as the fallback — the same layout main/speechDownloader.js writes
 * (`<userData>/speech-engine/`). Both are parameters so a test can point them
 * anywhere.
 *
 * The fallback used to be the empty string, which quietly made the "documented
 * drop-in directory" the process's own working directory: `hasBinary('')` is
 * false and `resolveWeights('')` resolves against cwd, so a binary and a model
 * that WERE installed next to the engine were invisible to it. Defaulting to
 * the engine's own package directory is what makes a bundled binary findable
 * without the supervisor having to be told where it was put.
 */
const engineDir = path.dirname(fileURLToPath(import.meta.url));
const binDir = String(args['bin-dir'] ?? env.LD_SPEECH_BIN_DIR ?? path.join(engineDir, 'bin'));
const modelsDir = String(args.modelsDir ?? env.LD_SPEECH_MODELS_DIR ?? path.join(engineDir, 'models'));

/**
 * The catalog model to transcribe with.
 *
 * The renderer's selection has to reach the decoder. Without this the engine
 * always resolved the catalog DEFAULT (`large-v3`, ~2.9 GB) and reported "model
 * not installed" no matter which smaller model the user had actually
 * downloaded — an install wizard that worked perfectly and still left the
 * engine unable to start.
 */
const modelId = String(args.model ?? env.LD_SPEECH_MODEL ?? '');

/**
 * Build the engine this run was asked for.
 *
 * WHY A REAL ENGINE FAILS LOUDLY HERE. If `--engine=whisper` is requested and
 * the binary or the weights are missing, the process exits 2 with a message
 * naming what to install. It does NOT fall back to the canned engine.
 *
 * That fallback is the single most dangerous thing this program could do: a
 * green "listening" badge attached to a process emitting a string it wrote
 * itself, on a sanctuary screen, during a service. `src/speech/engineTruth.js`
 * exists to make that unreachable in the UI, and this is the other half of the
 * same rule — make it unreachable in the engine.
 *
 * WHICH IS WHY `auto` IS NOT `whisper` WITH A SAFETY NET, and is not a
 * relaxation of that rule. `whisper` stays strict and still exits 2. `auto` is
 * the mode the supervisor launches, and it exists because the alternative is
 * worse in a specific way: the app's default provider is whispercpp, so a
 * strict default means every fresh install forks an engine that immediately
 * dies, on every start, until a multi-gigabyte download completes.
 *
 * The danger the rule guards against is falling back SILENTLY, and `auto` is
 * loud on both channels the app actually reads:
 *
 *   - the health payload says `backend: "fake"`, which `engineTruth.js` turns
 *     into a visible label on the panel and in settings, and which makes the
 *     output ineligible to become a sendable suggestion; and
 *   - this function prints the reason once, naming the path that is missing.
 *
 * @returns {object} an engine implementing the v1 contract
 */
function buildEngine() {
  if (engineKind === 'fake') return createFakeEngine({ bus });

  if (engineKind === 'whisper' || engineKind === 'auto') {
    const soft = engineKind === 'auto';
    try {
      return createWhisperEngine({
        bus,
        binDir,
        modelsDir,
        modelId: modelId || undefined,
      });
    } catch (error) {
      if (soft) {
        const missing = error?.code === 'unavailable'
          ? `binary at ${path.join(binDir, binaryName())}, or weights for ` +
            `"${modelId || '(catalog default)'}" in ${modelsDir}`
          : error?.message;
        // One line, once, naming what is missing: the only record that the app
        // is emitting canned output by default rather than because someone
        // asked for it.
        console.error(
          `speech-engine: auto — whisper.cpp is not usable (${missing}); ` +
          'running the canned engine. Output is labelled "fake".'
        );
        return createFakeEngine({ bus });
      }

      const detail = error?.code === 'unavailable'
        ? 'The whisper.cpp binary or its model weights are not installed. Use the ' +
          '"Install speech engine" button in Settings, or run with --engine=fake.'
        : 'The whisper.cpp engine could not be initialised.';
      console.error(`speech-engine: ${detail}`);
      process.exit(2);
    }
  }

  // An unknown engine name is a configuration error, and guessing at one is
  // exactly how a typo becomes a wrong engine mid-service.
  console.error(`speech-engine: unknown engine "${engineKind}". Use "fake", "whisper", or "auto".`);
  process.exit(2);
  return null;
}

// Parent-process mirror: LyricDisplay's supervisor subscribes over the fork
// IPC channel and relays recognized messages to the renderer. The WebSocket
// transport below subscribes to the SAME bus — one emission point, two sinks,
// so a renderer WebSocket drop never loses the transcript log.
bus.subscribe((message) => {
  if (typeof process.send === 'function') {
    try {
      process.send(message);
    } catch {
      // Parent went away; the HTTP surface keeps serving.
    }
  }
});

const handle = createSpeechEngineServer({
  token,
  host,
  bus,
  engine: buildEngine(),
});

// The renderer's PCM ingest: same loopback server, same token, same bus —
// attached only after the REST surface bound successfully. The bus is the
// single emission point (see bus.js), so everything a WebSocket client sees
// is byte-for-byte what the parent-process mirror sends to LyricDisplay.
const stream = attachWebSocketTransport(handle.server, {
  token,
  bus,
  engine: handle.engine,
  host,
});

const shutdown = () => {
  try {
    stream.close();
  } catch {
    // best effort — the HTTP close below is the real gate
  }
  handle
    .close()
    .catch(() => {})
    .finally(() => process.exit(0));
  // Safety net: never hang a shutdown the supervisor is escalating.
  setTimeout(() => process.exit(0), 1000).unref();
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

handle
  .listen(port, host)
  .then(({ port: boundPort, host: boundHost }) => {
    // No token in this line — logs must never carry secrets.
    console.log(`speech-engine [${handle.engine.kind}] listening on http://${boundHost}:${boundPort}`);
    if (typeof process.send === 'function') {
      process.send({
        status: 'ready',
        host: boundHost,
        port: boundPort,
        apiVersion: SPEECH_PROTOCOL_VERSION,
        // Where the renderer dials in (plan section 3): the supervisor and
        // the renderer must agree on ONE path constant.
        wsPath: WS_PATH,
      });
    }
  })
  .catch((error) => {
    if (error?.code === 'EADDRINUSE') {
      if (typeof process.send === 'function') {
        process.send({ status: 'error', error: 'EADDRINUSE', port });
      }
      console.error(`speech-engine: port ${port} is already in use`);
      process.exit(1);
    }
    // Loopback refusal and bind failures land here, loudly and non-zero.
    console.error(`speech-engine: failed to start: ${error.message}`);
    if (typeof process.send === 'function') {
      process.send({ status: 'error', error: error.code || 'bind-failed', message: error.message });
    }
    process.exit(1);
  });
